/* ============================================================================
 * QuetDoc QRcode — MIGRATION v5.0: PACKING LIST (KHOẢNG THÙNG -> SIZE) (25/09/2026)
 * ----------------------------------------------------------------------------
 * Cách chạy: Supabase Dashboard -> SQL Editor -> New query -> dán TOÀN BỘ file
 * này -> Run. Chạy lại nhiều lần vẫn an toàn.
 *
 * - Bảng packing_ranges: 1 dòng = 1 khoảng thùng của 1 chỉ thị
 *   (chi_thi, size, doi_thung, so_thung, tong_doi, thung_tu, thung_den, po, art).
 * - Quy tắc mapping (đã kiểm chứng với hệ cũ trên dữ liệu thật AE2608506:
 *   P=91 thùng, Q=546 đôi, 92 mã duy nhất):
 *     số thứ tự thùng = phần số sau ký tự "6" ở đuôi mã QR
 *     (VD "AE260850660003" -> 3; "AD260000861537" -> 1537),
 *   rồi tìm khoảng [thung_tu, thung_den] chứa nó -> ra SIZE + số đôi/thùng.
 * - App dùng bảng này để tự điền Size/PO khi quét (không cần OCR/pad),
 *   và xuất Báo cáo sản lượng theo đúng mẫu packing list.
 * ========================================================================== */

create table if not exists public.packing_ranges (
  chi_thi text not null,
  size text not null,
  doi_thung integer not null default 6,
  so_thung integer not null default 0,
  tong_doi integer not null default 0,
  thung_tu integer not null,
  thung_den integer not null,
  po text not null default '',
  art text not null default '',
  updated_at timestamptz not null default now(),
  primary key (chi_thi, thung_tu, thung_den),
  check (thung_tu >= 1 and thung_den >= thung_tu and doi_thung >= 0)
);
alter table public.packing_ranges enable row level security;

/* Chạy lại an toàn nếu bảng đã tồn tại từ bản nháp thiếu cột: */
alter table public.packing_ranges add column if not exists size text not null default '';
alter table public.packing_ranges add column if not exists doi_thung integer not null default 6;
alter table public.packing_ranges add column if not exists so_thung integer not null default 0;
alter table public.packing_ranges add column if not exists tong_doi integer not null default 0;
alter table public.packing_ranges add column if not exists thung_tu integer not null default 1;
alter table public.packing_ranges add column if not exists thung_den integer not null default 1;
alter table public.packing_ranges add column if not exists po text not null default '';
alter table public.packing_ranges add column if not exists art text not null default '';
alter table public.packing_ranges add column if not exists updated_at timestamptz not null default now();
/* Đảm bảo primary key cho ON CONFLICT (nếu bảng cũ chưa có): */
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'packing_ranges_pkey') then
    alter table public.packing_ranges add primary key (chi_thi, thung_tu, thung_den);
  end if;
end $$;

drop policy if exists "packing_read" on public.packing_ranges;
create policy "packing_read" on public.packing_ranges
  for select to authenticated using (true);
drop policy if exists "packing_admin_write" on public.packing_ranges;
create policy "packing_admin_write" on public.packing_ranges
  for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create index if not exists packing_ranges_chi_thi_idx on public.packing_ranges (chi_thi);

